create extension if not exists pgcrypto;
do $$ begin create type public.prediction_status as enum ('pending','win','loss','void'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique not null check(char_length(username) between 3 and 30),display_name text,country text,bio text check(char_length(bio)<=160),avatar_url text,is_adult_confirmed boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.competitions(id uuid primary key default gen_random_uuid(),sport text not null default 'football',name text not null,country text,external_id text unique);
create table if not exists public.events(id uuid primary key default gen_random_uuid(),competition_id uuid references public.competitions(id),home_name text not null,away_name text not null,kickoff_at timestamptz not null,status text not null default 'scheduled',home_score int,away_score int,external_id text unique,created_at timestamptz not null default now());
create table if not exists public.markets(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id) on delete cascade,market_type text not null,selection text not null,reference_odds numeric(8,3) not null check(reference_odds>1),captured_at timestamptz not null default now(),provider text,created_at timestamptz not null default now());
create table if not exists public.predictions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,event_id uuid not null references public.events(id),market_type text not null,selection text not null,reference_odds numeric(8,3) not null check(reference_odds>1),odds_captured_at timestamptz not null,confidence smallint not null check(confidence between 1 and 10),units smallint not null default 1 check(units between 1 and 5),analysis text check(char_length(analysis)<=800),status public.prediction_status not null default 'pending',closing_odds numeric(8,3),settled_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.follows(follower_id uuid not null references public.profiles(id) on delete cascade,followed_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(follower_id,followed_id),check(follower_id<>followed_id));
create table if not exists public.prediction_likes(user_id uuid not null references public.profiles(id) on delete cascade,prediction_id uuid not null references public.predictions(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,prediction_id));
create table if not exists public.comments(id uuid primary key default gen_random_uuid(),prediction_id uuid not null references public.predictions(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,body text not null check(char_length(body) between 1 and 1000),created_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists public.ratings(user_id uuid not null references public.profiles(id) on delete cascade,scope_type text not null check(scope_type in('overall','competition','market')),scope_key text not null,rating numeric(5,2) not null check(rating between 0 and 100),confidence text not null check(confidence in('very_low','low','medium','high','very_high')),sample_size int not null default 0,roi numeric(9,4),clv numeric(9,4),hit_rate numeric(9,4),updated_at timestamptz not null default now(),primary key(user_id,scope_type,scope_key));
create table if not exists public.blocks(blocker_id uuid not null references public.profiles(id) on delete cascade,blocked_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(blocker_id,blocked_id),check(blocker_id<>blocked_id));
create table if not exists public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id),target_type text not null check(target_type in('profile','prediction','comment')),target_id uuid not null,reason text not null check(char_length(reason) between 3 and 500),status text not null default 'open',created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ declare base_username text;candidate text; begin base_username:=lower(regexp_replace(coalesce(nullif(new.raw_user_meta_data->>'username',''),split_part(coalesce(new.email,'predictor'),'@',1),'predictor'),'[^a-zA-Z0-9_]','','g'));if char_length(base_username)<3 then base_username:='predictor';end if;base_username:=left(base_username,24);candidate:=base_username;if exists(select 1 from public.profiles where username=candidate) then candidate:=left(base_username,24)||'_'||left(new.id::text,4);end if;insert into public.profiles(id,username) values(new.id,candidate) on conflict(id) do nothing;insert into public.ratings(user_id,scope_type,scope_key,rating,confidence,sample_size) values(new.id,'overall','all',50,'very_low',0) on conflict(user_id,scope_type,scope_key) do nothing;return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.create_prediction_from_market(p_market_id uuid,p_confidence smallint,p_units smallint default 1,p_analysis text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare m public.markets%rowtype;e public.events%rowtype;pid uuid;begin if auth.uid() is null then raise exception 'Authentication required';end if;if p_confidence not between 1 and 10 then raise exception 'Confidence must be 1-10';end if;if p_units not between 1 and 5 then raise exception 'Units must be 1-5';end if;if char_length(coalesce(p_analysis,''))>800 then raise exception 'Analysis is too long';end if;select * into m from public.markets where id=p_market_id;if not found then raise exception 'Market snapshot not found';end if;select * into e from public.events where id=m.event_id;if now()>=e.kickoff_at-interval '5 minutes' then raise exception 'Predictions are closed for this event';end if;if m.captured_at<now()-interval '10 minutes' then raise exception 'Reference odds snapshot is stale';end if;insert into public.predictions(user_id,event_id,market_type,selection,reference_odds,odds_captured_at,confidence,units,analysis) values(auth.uid(),m.event_id,m.market_type,m.selection,m.reference_odds,m.captured_at,p_confidence,p_units,nullif(trim(p_analysis),'')) returning id into pid;return pid;end;$$;
revoke all on function public.create_prediction_from_market(uuid,smallint,smallint,text) from public;grant execute on function public.create_prediction_from_market(uuid,smallint,smallint,text) to authenticated;
create or replace function public.protect_prediction_core() returns trigger language plpgsql as $$ begin if new.user_id<>old.user_id or new.event_id<>old.event_id or new.market_type<>old.market_type or new.selection<>old.selection or new.reference_odds<>old.reference_odds or new.odds_captured_at<>old.odds_captured_at or new.confidence<>old.confidence or new.units<>old.units or new.created_at<>old.created_at then raise exception 'Prediction core fields are immutable';end if;if coalesce(auth.role(),'')<>'service_role' and(new.status<>old.status or new.closing_odds is distinct from old.closing_odds or new.settled_at is distinct from old.settled_at) then raise exception 'Users cannot settle predictions';end if;if coalesce(auth.role(),'')<>'service_role' and old.status<>'pending' and new.analysis is distinct from old.analysis then raise exception 'Settled prediction analysis is locked';end if;return new;end;$$;
drop trigger if exists trg_protect_prediction_core on public.predictions;create trigger trg_protect_prediction_core before update on public.predictions for each row execute function public.protect_prediction_core();
alter table public.profiles enable row level security;alter table public.competitions enable row level security;alter table public.events enable row level security;alter table public.markets enable row level security;alter table public.predictions enable row level security;alter table public.follows enable row level security;alter table public.prediction_likes enable row level security;alter table public.comments enable row level security;alter table public.ratings enable row level security;alter table public.blocks enable row level security;alter table public.reports enable row level security;
create policy "profiles readable" on public.profiles for select using(true);create policy "own profile update" on public.profiles for update using(auth.uid()=id) with check(auth.uid()=id);create policy "competitions readable" on public.competitions for select using(true);create policy "events readable" on public.events for select using(true);create policy "markets readable" on public.markets for select using(true);create policy "predictions readable" on public.predictions for select using(true);create policy "edit own pending analysis" on public.predictions for update using(auth.uid()=user_id and status='pending') with check(auth.uid()=user_id);create policy "follows readable" on public.follows for select using(true);create policy "create own follows" on public.follows for insert with check(auth.uid()=follower_id);create policy "delete own follows" on public.follows for delete using(auth.uid()=follower_id);create policy "likes readable" on public.prediction_likes for select using(true);create policy "create own likes" on public.prediction_likes for insert with check(auth.uid()=user_id);create policy "delete own likes" on public.prediction_likes for delete using(auth.uid()=user_id);create policy "comments readable" on public.comments for select using(deleted_at is null);create policy "create own comments" on public.comments for insert with check(auth.uid()=user_id);create policy "soft-delete own comments" on public.comments for update using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "ratings readable" on public.ratings for select using(true);create policy "read own blocks" on public.blocks for select using(auth.uid()=blocker_id);create policy "create own blocks" on public.blocks for insert with check(auth.uid()=blocker_id);create policy "delete own blocks" on public.blocks for delete using(auth.uid()=blocker_id);create policy "create own reports" on public.reports for insert with check(auth.uid()=reporter_id);create policy "read own reports" on public.reports for select using(auth.uid()=reporter_id);
create index if not exists predictions_user_created_idx on public.predictions(user_id,created_at desc);create index if not exists predictions_event_created_idx on public.predictions(event_id,created_at desc);create index if not exists markets_event_captured_idx on public.markets(event_id,captured_at desc);create index if not exists events_kickoff_idx on public.events(kickoff_at);create index if not exists follows_followed_idx on public.follows(followed_id);create index if not exists comments_prediction_idx on public.comments(prediction_id,created_at);
